  | 1, (StA, S1) => [SWin 2;SCycR 2;SWinR 5]
  | 1, (StB, S0) => [SWin 2;SCycR 2;SWinR 4]
  | 1, (StB, S1) => []
  | 1, (StC, S0) => [SWin 2;SCycR 2;SWin 1;SWinR 7;SCycL 2 0;SWin 3]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 2;SCycR 2;SWinR 2]
  | 1, (StD, S1) => [SWin 2]
  | _, _ => []
  end.

