Lemma bootl_1RB0LB_1LC0RC_1RA0LD_1LC1LD :
  stepn tm 17 InitES = Some (lift (fam_cfg FAM ([0;1], 0, 0))).
Proof.
  assert (H : match csteps tm 17 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0;1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 17 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

