    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact iarm_lhs_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact iarm_rhs_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - lia.
