  - exact farm_reach_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact farm_lhs_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact farm_rhs_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact nrules_sound_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact vis_ok_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
  - exact bootl_1RB0LB_1LC0RC_1RA0LD_1LC1LD.
Qed.

