  match r, ph with
  | 1, 0 => farm1_0_1RB0LC_1LA1RD_0RD1LC_1RB1RA
  | 1, 1 => farm1_1_1RB0LC_1LA1RD_0RD1LC_1RB1RA
  | 1, 2 => farm1_2_1RB0LC_1LA1RD_0RD1LC_1RB1RA
  | 1, 3 => farm1_3_1RB0LC_1LA1RD_0RD1LC_1RB1RA
  | _, _ => farm1_0_1RB0LC_1LA1RD_0RD1LC_1RB1RA  (* unreachable: 0 < r < N0 + st *)
  end.

