  | _, _ => farm1_0_1RB0LC_1LC1RD_0RB1LC_1LA1RA  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0LC_1LC1RD_0RB1LC_1LA1RA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 1, 1 => 1 | 1, 2 => 1 | _, _ => 0 end.
Definition fm2_1RB0LC_1LC1RD_0RB1LC_1LA1RA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | 1, 2 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
