  | StC, S0 => mk S0 DR StD
  | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S1 DL StA
  | StD, S1 => mk S1 DR StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0LC_1LC1RD_0RD1LC_1LA1RA pins_1RB0LC_1LC1RD_0RD1LC_1LA1RA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LC_1LC1RD_0RD1LC_1LA1RA : Fam := mkFam 2 [[S1;S1;S1];[S1;S1;S0]] [] [[S1];[S0;S1];[]] Binary 1 [mkFill 0 [] 0 [] 1;mkFill 1 [] 0 [1] 2;mkFill 0 [] 0 [] 0] StA S0 false [S1].
Local Notation FAM := fam_1RB0LC_1LC1RD_0RD1LC_1LA1RA.

(** ** The ladder, as DATA

    0 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list (LRule * list rstep) :=
  [].
Local Notation lad := lad_1RB0LC_1LC1RD_0RD1LC_1LA1RA.

Definition rules_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_1LC1RD_0RD1LC_1LA1RA.

Lemma ladder_ok_1RB0LC_1LC1RD_0RD1LC_1LA1RA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_1LC1RD_0RD1LC_1LA1RA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_1LC1RD_0RD1LC_1LA1RA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(** ** What this board establishes

    0 of 0 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 0 of them
    collapse to 4 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    0 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list (LRule * list rstep) :=
  [].
Definition nrules_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list LRule := map fst nlad_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
Local Notation nrules := nrules_1RB0LC_1LC1RD_0RD1LC_1LA1RA.

Lemma nladder_ok_1RB0LC_1LC1RD_0RD1LC_1LA1RA : check_ladder tm [] nlad_1RB0LC_1LC1RD_0RD1LC_1LA1RA = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB0LC_1LC1RD_0RD1LC_1LA1RA : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB0LC_1LC1RD_0RD1LC_1LA1RA. Qed.

Definition iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA : LRule :=
  mkLRule (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]))
          (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0])) 0 1.
Definition ch_iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list nseg :=
  [NCh [RB (SCycR 3);RB (SWin 6);RB (SCycL 3 0);RB (SWin 1);RB (SWinL 7)]].
Lemma ok_iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA :
  check_narm tm true false nrules iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA ch_iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA : LRule :=
  mkLRule (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S1]))
          (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1])) 0 1.
Definition ch_farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list nseg :=
  [NCh [RB (SWin 3);RB (SCycR 3);RB (SWin 1);RB (SWinR 3);RB (SCycL 3 0);RB (SWin 4);RB (SWinL 7)]].
Lemma ok_farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA :
  check_narm tm true true nrules farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA ch_farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_1_1RB0LC_1LC1RD_0RD1LC_1LA1RA : LRule :=
  mkLRule (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S0;S1]))
          (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S1;S0])) 0 1.
Definition ch_farm1_1_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list nseg :=
  [NCh [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SCycL 3 0);RB (SWin 4);RB (SWinL 7)]].
Lemma ok_farm1_1_1RB0LC_1LC1RD_0RD1LC_1LA1RA :
  check_narm tm true true nrules farm1_1_1RB0LC_1LC1RD_0RD1LC_1LA1RA ch_farm1_1_1RB0LC_1LC1RD_0RD1LC_1LA1RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_2_1RB0LC_1LC1RD_0RD1LC_1LA1RA : LRule :=
  mkLRule (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [S1;S1;S0] [S1;S1;S0] 1 0 []))
          (mkC StA (mkS [S1] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1])) 0 1.
Definition ch_farm1_2_1RB0LC_1LC1RD_0RD1LC_1LA1RA : list nseg :=
  [NCh [RB (SWin 3);RB (SCycR 3);RB (SWinR 2);RB (SCycL 3 0);RB (SWin 4);RB (SWinL 7)]].
Lemma ok_farm1_2_1RB0LC_1LC1RD_0RD1LC_1LA1RA :
  check_narm tm true true nrules farm1_2_1RB0LC_1LC1RD_0RD1LC_1LA1RA ch_farm1_2_1RB0LC_1LC1RD_0RD1LC_1LA1RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LC_1LC1RD_0RD1LC_1LA1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA
  | _, _ => iarm0_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0LC_1LC1RD_0RD1LC_1LA1RA (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA
  | 1, 1 => farm1_1_1RB0LC_1LC1RD_0RD1LC_1LA1RA
  | 1, 2 => farm1_2_1RB0LC_1LC1RD_0RD1LC_1LA1RA
  | _, _ => farm1_0_1RB0LC_1LC1RD_0RD1LC_1LA1RA  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0LC_1LC1RD_0RD1LC_1LA1RA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 1, 1 => 1 | 1, 2 => 1 | _, _ => 0 end.
Definition fm2_1RB0LC_1LC1RD_0RD1LC_1LA1RA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 1, 1 => 0 | 1, 2 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0LC_1LC1RD_0RD1LC_1LA1RA (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 0]
  | 1, (StA, S1) => [SWin 3;SCycR 3;SWinR 3]
  | 1, (StB, S0) => [SWin 3;SCycR 3;SWin 1]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 3;SCycR 3;SWin 1;SWinR 3;SCycL 3 0;SWinL 5]
  | 1, (StC, S1) => [SWin 3;SCycR 3;SWinR 4]
  | 1, (StD, S0) => [SWin 3;SCycR 3;SWinR 2]
  | 1, (StD, S1) => [SWin 2]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_1RB0LC_1LC1RD_0RD1LC_1LA1RA (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | _, _ => []
  end.

(** The visit phase of each instruction ([LadderCheckNestPvTr]), and the
    fills it takes the phase cycle to reach it from each phase. *)
Definition pvf_1RB0LC_1LC1RD_0RD1LC_1LA1RA (t : Instr) : nat :=
  match t with
  | (StA, S0) => 0
  | (StA, S1) => 0
  | (StB, S0) => 1
  | (StB, S1) => 0
  | (StC, S0) => 0
  | (StC, S1) => 0
  | (StD, S0) => 0
  | (StD, S1) => 0
  end.

Definition kcyc_1RB0LC_1LC1RD_0RD1LC_1LA1RA (tg ph : nat) : nat :=
  match tg, ph with
  | 0, 0 => 0
  | 0, 1 => 2
  | 0, 2 => 1
  | 1, 0 => 1
  | 1, 1 => 0
  | 1, 2 => 2
  | _, _ => 0
  end.

Lemma pvlt_1RB0LC_1LC1RD_0RD1LC_1LA1RA : forall t, pvf_1RB0LC_1LC1RD_0RD1LC_1LA1RA t < 3.
Proof. intros [q s]; destruct q, s; vm_compute; lia. Qed.

Lemma cyc_1RB0LC_1LC1RD_0RD1LC_1LA1RA : forall t ph, ph < 3 ->
  exists k, phto FAM k ph = pvf_1RB0LC_1LC1RD_0RD1LC_1LA1RA t.
Proof.
  intros t ph Hph. exists (kcyc_1RB0LC_1LC1RD_0RD1LC_1LA1RA (pvf_1RB0LC_1LC1RD_0RD1LC_1LA1RA t) ph).
  destruct t as [q s]; destruct q, s;
    (do 3 (destruct ph as [|ph]; [vm_compute; reflexivity|])); lia.
Qed.

Lemma iarm_reach_1RB0LC_1LC1RD_0RD1LC_1LA1RA : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_1RB0LC_1LC1RD_0RD1LC_1LA1RA d r)) (lr_rhs (iarm_1RB0LC_1LC1RD_0RD1LC_1LA1RA d r)).
