Lemma bootl_1RB0LC_1LC1RD_0RD1LC_1LA1RA :
  stepn tm 41 InitES = Some (lift (fam_cfg FAM ([1], 0, 2))).
Proof.
  assert (H : match csteps tm 41 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 2))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 41 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestPvTr.boardPv_neverqhtr]. *)
Theorem nqhtr_1RB0LC_1LC1RD_0RD1LC_1LA1RA : NeverQuasiHaltsTr tm_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
Proof.
  eapply (boardPv_neverqhtr tm_1RB0LC_1LC1RD_0RD1LC_1LA1RA pins_1RB0LC_1LC1RD_0RD1LC_1LA1RA FAM 3
                           iarm_1RB0LC_1LC1RD_0RD1LC_1LA1RA 0 1
                           farm_1RB0LC_1LC1RD_0RD1LC_1LA1RA 1 1
                           fm1_1RB0LC_1LC1RD_0RD1LC_1LA1RA fm2_1RB0LC_1LC1RD_0RD1LC_1LA1RA pvf_1RB0LC_1LC1RD_0RD1LC_1LA1RA
                           nrules vsegs_1RB0LC_1LC1RD_0RD1LC_1LA1RA vis_1RB0LC_1LC1RD_0RD1LC_1LA1RA
                           [1] 2).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - exact pvlt_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
  - exact cyc_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
  - exact fm12_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
  - exact iarm_lhs_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
  - exact iarm_rhs_1RB0LC_1LC1RD_0RD1LC_1LA1RA.
  - lia.
  - lia.
