Definition mk_1RB0LC_1RC1RD_0RD1LC_1LA1RA (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB0LC_1RC1RD_0RD1LC_1LA1RA.

(** 1RB0LC_1RC1RD_0RD1LC_1LA1RA *)
Definition tm_1RB0LC_1RC1RD_0RD1LC_1LA1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StC
  | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DR StD
  | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S1 DL StA
  | StD, S1 => mk S1 DR StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
