Local Notation tm := (tm_wrap_trs tm_1RB0LC_1RC1RD_0RD1LC_1LA1RA pins_1RB0LC_1RC1RD_0RD1LC_1LA1RA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0LC_1RC1RD_0RD1LC_1LA1RA : Fam := mkFam 2 [[S1;S1;S1];[S0;S1;S1]] [S1] [[S0;S1];[];[S0;S0;S1];[S1;S0;S1]] Binary 1 [mkFill 0 [] 0 [] 3;mkFill 1 [] 0 [] 0;mkFill 1 [] 0 [] 1;mkFill 0 [] 0 [] 2] StC S0 false [].
Local Notation FAM := fam_1RB0LC_1RC1RD_0RD1LC_1LA1RA.

(** ** The ladder, as DATA

    0 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0LC_1RC1RD_0RD1LC_1LA1RA : list (LRule * list rstep) :=
  [].
Local Notation lad := lad_1RB0LC_1RC1RD_0RD1LC_1LA1RA.

Definition rules_1RB0LC_1RC1RD_0RD1LC_1LA1RA : list LRule := map fst lad.
Local Notation rules := rules_1RB0LC_1RC1RD_0RD1LC_1LA1RA.

Lemma ladder_ok_1RB0LC_1RC1RD_0RD1LC_1LA1RA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0LC_1RC1RD_0RD1LC_1LA1RA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0LC_1RC1RD_0RD1LC_1LA1RA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(** ** What this board establishes

    0 of 0 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 0 of them
    collapse to 5 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1] [S0;S1;S1] 1 0 [S1;S1;S1]))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1] [S1;S1;S1] 1 0 [S0;S1;S1])) 6 4.
Definition ch_iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA : list rstep := [RB (SWin 1);RB (SCycR 3);RB (SWin 2);RB (SCycL 3 0);RB (SWin 1)].
Lemma ok_iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA :
  check_arm tm true false rules iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA
            ch_iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LC_1RC1RD_0RD1LC_1LA1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA
  | _, _ => iarm0_0_1RB0LC_1RC1RD_0RD1LC_1LA1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

