Lemma bootl_1RB0LC_1RC1RD_0RD1LC_1LA1RA :
  stepn tm 49 InitES = Some (lift (fam_cfg FAM ([0], 0, 1))).
Proof.
  assert (H : match csteps tm 49 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 1))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 49 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

